"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[8341],{91534(a,n,e){e.r(n),e.d(n,{assets:()=>s,contentTitle:()=>r,default:()=>d,frontMatter:()=>u,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"learning/courses/quantum-computing-in-practice/running-quantum-circuits","title":"Menjalankan litar kuantum","description":"Pandangan tahap tinggi tentang asas menjalankan pengkomputeran kuantum berskala utiliti.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/quantum-computing-in-practice/running-quantum-circuits.mdx","sourceDirName":"learning/courses/quantum-computing-in-practice","slug":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits","permalink":"/learning/courses/quantum-computing-in-practice/running-quantum-circuits","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/quantum-computing-in-practice/running-quantum-circuits.mdx","tags":[],"version":"current","frontMatter":{"title":"Menjalankan litar kuantum","sidebar_label":"Menjalankan litar kuantum","description":"Pandangan tahap tinggi tentang asas menjalankan pengkomputeran kuantum berskala utiliti.","notebook_path":"learning/courses/quantum-computing-in-practice/running-quantum-circuits.ipynb"},"sidebar":"tutorialsSidebar","previous":{"title":"Pengenalan","permalink":"/learning/courses/quantum-computing-in-practice/introduction"},"next":{"title":"QAOA berskala utiliti","permalink":"/learning/courses/quantum-computing-in-practice/utility-scale-qaoa"}}');var t=e(74848),k=e(28453);const u={title:"Menjalankan litar kuantum",sidebar_label:"Menjalankan litar kuantum",description:"Pandangan tahap tinggi tentang asas menjalankan pengkomputeran kuantum berskala utiliti.",notebook_path:"learning/courses/quantum-computing-in-practice/running-quantum-circuits.ipynb"},r=void 0,s={},m=[{value:"Gambaran pelajaran",id:"gambaran-pelajaran",level:2},{value:"Perkakasan \u2014 pemproses kuantum IBM",id:"perkakasan-pemproses-kuantum-ibm",level:2},{value:"Perisian: Qiskit dan Qiskit Runtime",id:"perisian-qiskit-dan-qiskit-runtime",level:2},{value:"litar Kuantum",id:"circuit-kuantum",level:2},{value:"Mereka bentuk litar kuantum: corak Qiskit",id:"mereka-bentuk-circuit-kuantum-corak-qiskit",level:2},{value:"Peta",id:"peta",level:3},{value:"Optimumkan",id:"optimumkan",level:3},{value:"Transpiler Qiskit",id:"transpiler-qiskit",level:4},{value:"Penindasan ralat",id:"penindasan-ralat",level:4},{value:"Laksanakan",id:"laksanakan",level:3},{value:"Pasca-proses",id:"pasca-proses",level:3},{value:"Kesimpulan",id:"kesimpulan",level:2}];function l(a){const n={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",h4:"h4",img:"img",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,k.R)(),...a.components},{IBMVideo:i}=n;return i||function(a,n){throw new Error("Expected "+(n?"component":"object")+" `"+a+"` to be defined: you likely forgot to import, pass, or provide it.")}("IBMVideo",!0),(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsxs)(n.p,{children:["Tonton video tentang litar kuantum dan primitif daripada Olivia Lanes, atau buka video dalam tetingkap berasingan di ",(0,t.jsx)(n.a,{href:"https://youtube.com/watch?v=NTplT4WnNbk",children:"YouTube."})]}),"\n",(0,t.jsx)(i,{id:"134063416",title:"In this video, Olivia Lanes explains quantum circuits and primitives. She covers Qiskit Runtime primitives estimator and sampler."}),"\n",(0,t.jsx)(n.h2,{id:"gambaran-pelajaran",children:"Gambaran pelajaran"}),"\n",(0,t.jsx)(n.p,{children:"Pelajaran ini akan menjadi pandangan tahap tinggi tentang asas menjalankan pengkomputeran kuantum berskala utiliti, daripada perkakasan kuantum yang digunakan kepada prinsip yang perlu dipertimbangkan semasa mereka bentuk litar kuantum. Sebaik-baiknya, menjelang akhir pelajaran ini, anda akan tahu:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Apakah sebenarnya komputer kuantum IBM\xae. Anda perlu mengetahui asas ciri perkakasan untuk mereka bentuk litar kuantum anda secara optimum untuk dijalankan padanya."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Apakah Qiskit, apakah primitif, dan cara kita boleh menggunakannya untuk mencipta dan melaksanakan litar kuantum."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Aliran kerja tipikal yang kita ikuti untuk menjalankan eksperimen pada skala. Ini termasuk memilih primitif terbaik untuk kes penggunaan anda, memetakan masalah kepada litar kuantum, dan menggunakan mitigasi dan penindasan ralat, yang membolehkan kita mendapatkan seberapa banyak kuasa daripada mesin-mesin ini sebanyak mungkin."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"perkakasan-pemproses-kuantum-ibm",children:"Perkakasan \u2014 pemproses kuantum IBM"}),"\n",(0,t.jsx)(n.p,{children:"Untuk memahami cara kita membuat pilihan optimum dalam mereka bentuk litar kuantum berskala besar, kita perlu mengetahui sedikit tentang perkakasan sebenar yang akan menjalankan litar ini. Jadi mari kita bincangkan secara ringkas qubit fizikal dan pemproses kuantum IBM."}),"\n",(0,t.jsxs)(n.p,{children:["Pemproses kuantum IBM dibina menggunakan qubit transmon pengalir super, yang merupakan litar elektrik yang terdiri daripada ",(0,t.jsx)(n.em,{children:"simpang Josephson"})," dan kapasitor yang disambungkan secara selari. Simpang Josephson adalah induktor tak linear yang dicipta daripada dua lapisan logam pengalir super yang bertindih dengan penghalang penebat di antara mereka. Pada suhu yang sangat rendah, elektron dalam pengalir super berpasangan membentuk apa yang dikenali sebagai pasangan cooper. Pasangan cooper boleh merentas secara spontan melalui penghalang penebat dari satu sisi simpang ke yang lain. Tingkah laku menyelinap ini menimbulkan sifat tak linear yang mencipta qubit kita."]}),"\n",(0,t.jsxs)(n.p,{children:["Talian penghantaran gelombang mikro difabrikasikan pada cip untuk menghantar isyarat gelombang mikro ke qubit. Apabila kita menggunakan denyutan gelombang mikro yang dikalibrasi dengan teliti \u2014 dengan frekuensi, amplitud, bentuk, dan tempoh yang khusus \u2014 ke talian-talian tersebut, kita boleh membuat qubit melakukan perkara-perkara tertentu. Ini membentuk asas get kuantum kita. Kita memfabrikasikan cip supaya qubit bersebelahan disambungkan dalam struktur kekisi khusus yang dipanggil kekisi hex berat. Sambungan ini \u2014 yang dipanggil ",(0,t.jsx)(n.em,{children:"topologi"})," \u2014 pemproses kita adalah faktor penting yang perlu dipertimbangkan semasa mereka bentuk litar, seperti yang akan kita bincangkan kemudian dalam pelajaran."]}),"\n",(0,t.jsx)(n.p,{children:"Arahan untuk denyutan gelombang mikro pergi dari komputer anda, melalui awan, dan ke elektronik kawalan suhu bilik, yang mentafsir arahan tersebut dan secara fizikal menjana denyutan. Selepas kotak kawalan suhu bilik mencipta denyutan, mereka bergerak melalui kabel ke dalam peti sejuk pencairan dan akhirnya ke cip kuantum. Isyarat masuk ke dalam resonator, melalui wayar ikatan, dan kemudian mengalir ke bawah talian penghantaran ke qubit kita."}),"\n",(0,t.jsxs)(n.p,{children:["IBM mempunyai berpuluh-puluh komputer kuantum di seluruh dunia, dan kita baru-baru ini menaik taraf armada kita untuk secara eksklusif mempunyai pemproses yang lebih besar daripada 100 qubit. Sesetengahnya terletak di pusat data kuantum IBM di bahagian utara New York dan digunakan melalui awan untuk kegunaan semua orang \u2014 dan sesetengahnya adalah sistem khas di premis yang menyokong rakan kongsi dalam Rangkaian IBM Quantum\xae. Anda boleh log masuk ke ",(0,t.jsx)(n.a,{href:"https://quantum.cloud.ibm.com",children:"quantum.cloud.ibm.com"})," untuk melihat pemproses mana yang anda ada akses."]}),"\n",(0,t.jsx)(n.p,{children:"Setiap pemproses menyenaraikan tiga metrik prestasi, yang kita bincangkan dalam pelajaran sebelumnya, tetapi sebagai peringatan, ia adalah: bilangan qubit, EPLG, dan CLOPS."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Bilangan qubit."})," Ini jelas: ia adalah bilangan jumlah qubit yang tersedia untuk digunakan pada pemproses kuantum tunggal. Untuk masalah berskala utiliti yang agak besar, anda perlu memastikan anda menggunakan pemproses yang mempunyai qubit yang mencukupi untuk dapat menangani masalah. Tetapi bilangan qubit sahaja bukan satu-satunya perkara yang penting."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"EPLG,"}),' atau "ralat per get berlapis." Ini adalah ukuran kualiti qubit dan get kuantum. Ia mengukur purata ralat yang diperkenalkan oleh setiap get dalam litar yang membelit qubit bersebelahan dalam rantai 100 qubit. Anda mahu ini sekecil mungkin.']}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"CLOPS,"}),' atau "operasi lapisan litar sesaat." Ini mengukur kelajuan pemproses. Ia mengukur berapa banyak lapisan litar ukur jejari kuantum yang dipanggil litar volume kuantum yang boleh dilaksanakan oleh unit pemprosesan kuantum (QPU) seunit masa. Semakin tinggi angkanya, semakin cepat kita boleh mengira.']}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Kepentingan setiap metrik ini berbeza-beza bergantung pada aplikasi tertentu, dan dalam pelajaran akan datang, kita akan melihat contoh-contoh nyata untuk melihat bagaimana setiap faktor ini boleh mempengaruhi hasil pengiraan."}),"\n",(0,t.jsx)(n.h2,{id:"perisian-qiskit-dan-qiskit-runtime",children:"Perisian: Qiskit dan Qiskit Runtime"}),"\n",(0,t.jsx)(n.p,{children:"Untuk mengubah masalah kuantum anda menjadi arahan untuk komputer kuantum, anda akan menggunakan Qiskit, kit pembangunan perisian sumber terbuka yang direka bentuk untuk kerja pada komputer kuantum yang dibangunkan oleh IBM. Terdapat juga Ekosistem Qiskit \u2014 koleksi tutorial dan fungsi perisian yang membina atau melanjutkan fungsi teras Qiskit \u2014 dan Qiskit Runtime \u2014 perkhidmatan pengkomputeran kuantum dan model pengaturcaraan yang membolehkan pengguna mereka bentuk dan mengoptimumkan beban kerja kuantum mereka dan melaksanakannya dengan cekap menggunakan Qiskit Runtime Primitives."}),"\n",(0,t.jsx)(n.p,{children:"Primitif adalah blok binaan kecil yang boleh anda gunakan untuk mereka bentuk litar atau kerja yang lebih besar. Dua primitif yang paling penting bagi kita adalah Sampler dan Estimator, yang akan kita bincangkan dengan lebih mendalam tidak lama lagi."}),"\n",(0,t.jsxs)(n.p,{children:["Dengan keluaran terkini Qiskit v1.0, Qiskit telah menjadi lebih berprestasi dan stabil daripada sebelumnya. Jadi, bagi anda yang baru bermula, anda datang pada masa yang tepat! Bagi anda yang sudah biasa dengan Qiskit, anda perlu memuat turun dan memasang semula versi terbaru. Untuk panduan pemasangan penuh, lawati panduan ",(0,t.jsx)(n.a,{href:"/guides/install-qiskit",children:"Pasang Qiskit"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"circuit-kuantum",children:"litar Kuantum"}),"\n",(0,t.jsxs)(n.p,{children:["Sekarang kita bersedia untuk membincangkan asas program kuantum: litar kuantum. Bahagian ini hanya akan berfungsi sebagai ulasan \u2014 jika anda tidak biasa dengan litar kuantum, kami mengesyorkan belajar tentangnya secara lebih mendalam dengan melawat pelajaran ",(0,t.jsx)(n.a,{href:"/learning/courses/basics-of-quantum-information/quantum-circuits/introduction",children:"litar Kuantum"}),' dalam kursus "Asas maklumat kuantum" sebelum meneruskan.']}),"\n",(0,t.jsx)(n.p,{children:"litar kuantum adalah rangkaian get kuantum dan pengukuran yang dihubungkan oleh wayar yang mewakili qubit, seperti yang ditunjukkan di bawah. litar kuantum boleh dibaca seperti nota muzik, dari kiri ke kanan, bermula pada masa 0 di sebelah kiri. Qubit maya \u2014 yang belum ditetapkan kepada qubit fizikal pada pemproses \u2014 disenaraikan dalam susunan menaik dari atas ke bawah."}),"\n",(0,t.jsx)(n.p,{children:'get diwakili oleh simbol berbeza pada wayar qubit yang terlibat. get satu-qubit \u2014 seperti get Hadamard, yang digambarkan di bawah (kotak dengan H) \u2014 hanya mempengaruhi qubit yang wayarnya diletakkan padanya. get pelbagai-qubit \u2014 seperti get CNOT, juga ditunjukkan di bawah (tanda tambah dalam bulatan dengan garisan yang disambungkan ke q0) \u2014 mempengaruhi dua atau lebih qubit. Dalam get CNOT yang digambarkan, keadaan q1 berubah mengikut keadaan q0. Selepas semua get dilakukan, kita boleh mengukur qubit, ditunjukkan oleh get hitam dengan simbol pengukuran. Hasil pengukuran ditulis ke dalam daftar klasik, bas "meas" bergarisan ganda di bawah.'}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Contoh litar kuantum mudah",src:e(54776).A+"",width:"2715",height:"1424"})}),"\n",(0,t.jsx)(n.p,{children:'Satu ciri penting litar adalah kedalamannya. Kedalaman litar kuantum adalah bilangan minimum "lapisan" get kuantum, yang dilaksanakan secara selari, yang diperlukan untuk melengkapkan litar. get kuantum boleh dilaksanakan secara selari (pada masa yang sama) apabila mereka tidak mempunyai sebarang qubit yang sama. Tetapi jika dua atau lebih get bertindak pada qubit yang sama maka kita tidak boleh melaksanakannya secara selari \u2014 ia mesti dilaksanakan dalam dua lapisan berasingan, satu selepas yang lain.'}),"\n",(0,t.jsx)(n.p,{children:"Ada cara lain yang kurang ketara untuk menentukan kedalaman litar, dengan memainkan semacam permainan. Peraturannya mudah: bermula dari mana-mana wayar qubit di sebelah kiri, anda mesti bergerak ke kanan dan mengira bilangan get yang anda temui dalam laluan anda. Anda boleh melompat ke wayar bersebelahan hanya apabila ia disambungkan ke wayar semasa anda oleh get pelbagai-qubit. Matlamatnya adalah untuk memaksimumkan bilangan get yang anda temui sepanjang laluan anda. Nombor maksimum ini juga kebetulan merupakan kedalaman litar."}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.img,{alt:"Contoh litar sembilan lapisan",src:e(77815).A+"",width:"3840",height:"1893"})}),"\n",(0,t.jsx)(n.p,{children:"Oleh kerana get kuantum mengambil masa untuk dilaksanakan, kedalaman litar secara kasar sepadan dengan jumlah masa yang diperlukan untuk komputer kuantum melaksanakan litar. Sesetengah mesin lebih sesuai untuk litar kedalaman besar daripada yang lain disebabkan masa penyahlengkapan qubit pada pemproses. Jadi, kita perlu mengetahui kedalaman litar untuk mengetahui sama ada ia boleh dijalankan pada peranti tertentu."}),"\n",(0,t.jsx)(n.h2,{id:"mereka-bentuk-circuit-kuantum-corak-qiskit",children:"Mereka bentuk litar kuantum: corak Qiskit"}),"\n",(0,t.jsx)(n.p,{children:"Jadi, bagaimana kita pergi tentang mereka bentuk dan menjalankan litar kuantum? Cara paling mudah untuk memahami aliran kerja pengkomputeran kuantum yang tipikal adalah melalui corak Qiskit. Corak Qiskit adalah rangka kerja konseptual yang membolehkan pengguna menjalankan beban kerja kuantum dengan melaksanakan langkah-langkah tertentu dengan perkakas modular. Ini membolehkan tugas pengkomputeran kuantum dilakukan oleh infrastruktur pengkomputeran heterogen yang berkuasa (CPU/GPU/QPU). Langkah-langkah boleh dilakukan sebagai perkhidmatan dan boleh menggabungkan pengurusan sumber, yang membolehkan kebolehkomposisian lancar keupayaan baharu apabila ia dibangunkan."}),"\n",(0,t.jsx)(n.p,{children:"Berikut adalah langkah-langkah utama, yang pengguna Qiskit yang berpengalaman mungkin akan mengenali."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Peta."})," Langkah ini memformalisasikan cara kita mengambil masalah umum yang kita minati dan mengetahui cara memetakannya ke komputer kuantum dalam bentuk litar kuantum."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Optimumkan."})," Dalam langkah ini kita menggunakan Transpiler Qiskit untuk menghalaukan dan meletakkan litar ke atas perkakasan qubit fizikal sebenar. Ini termasuk menterjemah get kuantum individu ke dalam urutan operasi yang dilakukan pada perkakasan serta pengoptimuman dalam susun atur get."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Laksanakan."})," Qiskit Runtime primitives menyediakan antara muka ke perkakasan IBM Quantum yang membolehkan litar yang ditranspilasi dijalankan. Langkah ini juga termasuk menggunakan teknik penindasan dan mitigasi ralat, yang sebahagian besarnya boleh diabstrakkan daripada pengguna."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Pasca-proses."})," Dalam langkah ini data daripada pemproses kuantum itu sendiri diproses, memberikan pengguna hasil yang berguna tentang masalah asal. Pada dasarnya, ini merangkumi sebarang analisis lanjut data yang diperoleh."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"peta",children:"Peta"}),"\n",(0,t.jsx)(n.p,{children:'Langkah Peta pada dasarnya bertanya soalan: "Bagaimana saya menterjemah masalah saya ke dalam litar kuantum yang boleh dijalankan secara munasabah pada perkakasan kuantum?" Tidak ada syak wasangka tentangnya: pemetaan adalah masalah yang sukar dan kawasan penyelidikan yang aktif. Tidak ada kaedah yang tidak boleh gagal yang menjamin kejayaan, tetapi terdapat garis panduan yang disyorkan dan contoh masalah yang sudah kita tahu cara memetakannya.'}),"\n",(0,t.jsx)(n.p,{children:"Garis panduan pertama adalah untuk membiarkan komputer klasik melakukan kerja apa pun yang lebih baik dilakukannya. Tugasan yang mudah untuk komputer klasik mungkin tidak akan mendapat manfaat daripada komputer kuantum. Komputer kuantum adalah untuk masalah yang sukar secara klasik. Sudah tentu, jika ini adalah kali pertama anda menggunakan Qiskit atau komputer kuantum, jangan risau tentang mencari masalah yang rumit secara pengkomputeran. Pecahkannya kepada masalah yang lebih kecil dan mudah ditelan yang boleh anda pelajari untuk menangani sebelum terus ke projek berskala utiliti."}),"\n",(0,t.jsx)(n.p,{children:"Seterusnya, terjemahkan hasil untuk masalah anda yang anda ingin ukur atau fahami ke dalam nilai jangkaan atau fungsi kos. Fungsi kos adalah fungsi khusus masalah yang mentakrifkan matlamat masalah sebagai sesuatu yang perlu diminimumkan atau dimaksimumkan. Ia boleh digunakan untuk melihat seberapa baik keadaan atau penyelesaian percubaan berprestasi berkenaan matlamat itu. Gagasan ini boleh digunakan untuk pelbagai aplikasi dalam kimia, pembelajaran mesin, kewangan, pengoptimuman, dan sebagainya \u2014 tidak semestinya penting dari subjek apa anda mendekati masalah."}),"\n",(0,t.jsx)(n.p,{children:"Juga ingat bahawa perkakasan yang akan anda gunakan mempunyai topologi tertentu, seperti yang kita bincangkan dalam bahagian perkakasan. Sesetengah qubit disambungkan, dan sesetengahnya tidak \u2014 anda perlu memetakan masalah anda ke litar yang menghormati topologi hex berat pemproses kuantum IBM."}),"\n",(0,t.jsx)(n.p,{children:"Buat masa ini, perkara yang paling penting untuk diingat adalah bahawa peringkat ini memerlukan latihan. Anda perlu mempunyai pemahaman yang baik bukan sahaja tentang masalah anda, tetapi juga tentang keupayaan perkakasan \u2014 dan kita akan melalui contoh-contoh dan kes penggunaan tertentu dalam pelajaran akan datang untuk melihat cara menyeimbangkan semua pertimbangan ini."}),"\n",(0,t.jsx)(n.h3,{id:"optimumkan",children:"Optimumkan"}),"\n",(0,t.jsx)(n.p,{children:"Seterusnya, kita perlu memilih pemproses kuantum yang mempunyai qubit yang mencukupi dengan kualiti yang cukup tinggi sehingga kita boleh menjalankan litar kuantum kita. Buat keputusan ini dipandu oleh tiga metrik yang kita bincangkan dalam bahagian perkakasan: bilangan qubit, EPLG, dan CLOPS."}),"\n",(0,t.jsx)(n.p,{children:"Kemudian kita mengoptimumkan litar kita untuk perkakasan yang dipilih. Pertama, kita perlu meletakkan dan menghalaukan litar kita dengan cekap. Susun atur merujuk kepada pemetaan qubit maya dalam litar ke qubit fizikal pada pemproses. Penghalaan merujuk kepada mengubah suai litar supaya sambungan antara qubit maya dalam litar sepadan dengan sambungan qubit fizikal pada pemproses. Terdapat beberapa perkara yang perlu diingat semasa peringkat susun atur dan penghalaan."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Tidak semua qubit disambungkan. Sesetengahnya sangat jauh dari satu sama lain pada cip, dan kita perlu mengurangkan atau menghapuskan interaksi jarak jauh di mana mungkin. Anda boleh menggunakan satu siri get SWAP antara qubit bersebelahan untuk mengalihkan maklumat qubit, tetapi get SWAP adalah mahal dan terdedah kepada ralat, jadi mungkin ada cara yang lebih baik untuk melakukan ini. Cuba elakkan terlalu banyak get SWAP yang mahal."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Susun atur dan penghalaan adalah proses berulang. Anda boleh melakukannya dengan tangan, tetapi terdapat juga alat Qiskit yang dipanggil ",(0,t.jsx)(n.code,{children:"mapomatic"}),", yang boleh membuat cadangan untuk susun atur qubit fizikal berdasarkan kadar ralat anggaran. Transpiler (yang akan kita bincangkan tidak lama lagi) juga boleh membuat cadangan yang dimaklumkan."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Seterusnya, kita boleh menyusun urutan get satu-qubit yang bertindak pada qubit yang sama menjadi get tunggal \u2014 dan kita juga kadang-kala boleh menghapuskan get atau kombinasi get yang tidak perlu. Sebagai contoh, sesetengah kombinasi get boleh dikurangkan kepada kombinasi yang lebih mudah \u2014 dan sebenarnya, kadang-kala kombinasi get mungkin bersamaan dengan operasi identiti, jadi kita boleh menghapuskannya. Anda boleh melakukan ini secara automatik menggunakan Transpiler Qiskit \u2014 tetapi anda juga boleh melakukannya secara manual berdasarkan get demi get jika anda mahukan lebih banyak kawalan."}),"\n",(0,t.jsx)(n.p,{children:"Setelah kita telah meningkatkan susun atur litar, penghalaan dan bilangan get \u2014 sama ada dengan tangan atau menggunakan Transpiler \u2014 kita biasanya ingin memvisualisasikan litar kita untuk memastikan masa semua get masuk akal. Terdapat argumen yang boleh anda tandai dalam Transpiler untuk memvisualisasikan garis masa litar anda, dan memastikan semuanya berbaris seperti yang anda jangkakan."}),"\n",(0,t.jsx)(n.h4,{id:"transpiler-qiskit",children:"Transpiler Qiskit"}),"\n",(0,t.jsx)(n.p,{children:"Seperti yang disebutkan sebelumnya, Transpiler Qiskit boleh digunakan untuk membantu dalam peringkat awal aliran kerja corak. Sekarang mari kita menyelami keupayaannya dengan lebih terperinci. Ia boleh menulis semula litar input yang diberikan supaya ia sepadan dengan topologi peranti kuantum tertentu dan mengoptimumkan litar untuk pelaksanaan dan ketahanan terhadap hingar. Ia juga menulis semula litar yang diberikan ke dalam get asas pemproses kuantum tertentu yang anda pilih untuk digunakan."}),"\n",(0,t.jsx)(n.p,{children:"Qiskit mempunyai empat saluran paip transpilasi terbina yang sepadan dengan tahap pengoptimuman yang berbeza, dan melainkan anda sudah biasa dengan pengoptimuman litar kuantum, kami mengesyorkan menggunakan salah satunya. Secara lalai, proses transpilasi merangkumi enam langkah ini:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Permulaan. Peringkat ini menjalankan sebarang laluan awal yang diperlukan sebelum kita mula menanamkan litar ke Backend. Ini biasanya melibatkan pembongkaran arahan tersuai dan menukar litar menjadi hanya get satu- dan dua-qubit."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Susun atur. Peringkat ini memetakan qubit maya dalam litar ke qubit fizikal pada Backend. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#layout-stage",children:"Peringkat Susun Atur"})," untuk maklumat lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Penghalaan. Peringkat ini berjalan selepas susun atur diterapkan dan menyuntik get (seperti get swap) ke dalam litar asal untuk menjadikannya serasi dengan sambungan Backend. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#routing-stage",children:"Peringkat Penghalaan"})," untuk maklumat lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:["Terjemahan. Peringkat ini menterjemah get dalam litar ke set asas Backend sasaran. Lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler#translation-stage",children:"Peringkat Terjemahan"})," untuk maklumat lanjut."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Pengoptimuman. Peringkat ini menjalankan gelung pengoptimuman utama berulang kali sehingga suatu syarat (seperti mencapai kedalaman sasaran tertentu) dicapai. Kita mempunyai empat tahap pengoptimuman yang berbeza untuk dipilih, diterangkan di bawah."}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:"Penjadualan. Peringkat ini adalah untuk sebarang laluan penjadualan yang menyedari perkakasan. Pada tahap tinggi, penjadualan boleh difikirkan sebagai memasukkan kelewatan ke dalam litar untuk mengambil kira masa terbiar pada qubit antara pelaksanaan arahan."}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Terdapat empat tahap pengoptimuman yang berkisar dari 0 hingga 3, di mana tahap pengoptimuman yang lebih tinggi mengambil lebih banyak masa dan usaha pengkomputeran tetapi mungkin menghasilkan litar yang lebih baik. Tahap pengoptimuman 0 dimaksudkan untuk eksperimen pencirian peranti dan, oleh itu, hanya memetakan litar input ke kekangan Backend sasaran, tanpa melakukan sebarang pengoptimuman. Tahap pengoptimuman 3 menghabiskan usaha paling banyak untuk mengoptimumkan litar. Walau bagaimanapun, oleh kerana banyak teknik pengoptimuman dalam Transpiler adalah berasaskan heuristik, menghabiskan lebih banyak usaha pengkomputeran tidak sentiasa menghasilkan peningkatan dalam kualiti litar output. Jika ini adalah minat lebih lanjut, lihat ",(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit/transpiler",children:"dokumentasi Transpiler"})," dalam dokumentasi Qiskit."]}),"\n",(0,t.jsx)(n.h4,{id:"penindasan-ralat",children:"Penindasan ralat"}),"\n",(0,t.jsx)(n.p,{children:"Langkah pertama dalam mengurangkan ralat dalam litar adalah mengoptimumkan susun atur, penghalaan, dan meminimumkan bilangan get, yang telah kita lakukan, sama ada menggunakan Transpiler atau sendiri. Sekarang mari kita bincangkan beberapa kaedah penindasan ralat yang lebih canggih."}),"\n",(0,t.jsx)(n.p,{children:'Penindasan ralat merujuk kepada kelas teknik yang mengubah litar semasa penyusunan untuk meminimumkan ralat. Ia berbeza daripada mitigasi ralat, yang akan kita bincangkan kemudian dalam bahagian "Laksanakan" di bawah. Dua bentuk penindasan ralat yang paling biasa yang kita gunakan adalah penyahgandingan dinamik dan pilinan Pauli:'}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsx)(n.li,{children:"Penyahgandingan dinamik digunakan untuk mengabaikan dengan berkesan sebahagian daripada hingar persekitaran yang diperkenalkan apabila qubit duduk terbiar. Dengan menggunakan satu siri get pada masa tertentu, anda boleh menjadikan hingar yang terkumpul dalam satu bahagian tempoh terbiar mengabaikan hingar dalam bahagian yang lain."}),"\n",(0,t.jsx)(n.li,{children:"Pilinan Pauli adalah cara memasukkan get rawak bukan untuk membatalkan hingar, seperti dalam penyahgandingan dinamik, tetapi untuk memudahkan hingar. Dengan memasukkan get rawak, ia menghalang kesan pelbagai ralat daripada terbina dengan cepat, dan menjadikan hingar lebih mudah dicirikan, kerana ia kini mempunyai sifat stokastik. Kaedah ini juga membentuk asas teknik mitigasi ralat yang berkuasa, yang akan kita bincangkan di bawah."}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"laksanakan",children:"Laksanakan"}),"\n",(0,t.jsx)(n.p,{children:"Sekarang kita bersedia untuk melaksanakan program kuantum. Qiskit Runtime primitives menyediakan antara muka ke perkakasan IBM Quantum, dan mereka juga mengabstrakkan penindasan dan mitigasi ralat daripada pengguna. Terdapat dua primitif untuk dipilih: Sampler dan Estimator."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-ibm-runtime/sampler",children:"Sampler Qiskit Runtime"})," menjalankan litar beberapa kali pada peranti kuantum, melakukan pengukuran pada setiap jalankan, dan membina semula taburan kebarangkalian daripada rentetan bit yang diperoleh. Semakin banyak jalankan (atau tembakan) yang dilakukan, semakin tepat hasilnya, tetapi ini memerlukan lebih banyak masa dan sumber kuantum. Secara khusus, ia mengira kebarangkalian mendapatkan setiap keadaan asas standard yang mungkin dengan mengukur keadaan yang disediakan oleh litar."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://docs.quantum.ibm.com/api/qiskit-ibm-runtime/estimator",children:"Estimator Qiskit Runtime"})," menggunakan proses algebra yang kompleks untuk menganggarkan nilai jangkaan pada peranti kuantum sebenar dengan mengurai boleh cerap kepada gabungan boleh cerap lain dengan asas eigen yang diketahui."]}),"\n",(0,t.jsxs)(n.p,{children:["Langkah Laksanakan juga adalah apabila kita boleh memilih strategi ",(0,t.jsx)(n.em,{children:"mitigasi ralat"}),". ",(0,t.jsx)(n.em,{children:"Mitigasi ralat"})," merujuk kepada teknik yang membolehkan pengguna mengurangkan ralat litar dengan memodelkan hingar peranti yang hadir semasa pelaksanaan. Biasanya, ini menghasilkan overhed pra-pemprosesan kuantum yang berkaitan dengan latihan model dan overhed pasca-pemprosesan klasik untuk memitigasi ralat dalam keputusan mentah menggunakan model yang dijana. Sebagai pertukaran untuk overhed ini, kita dapat memperoleh keputusan yang jauh lebih tepat."]}),"\n",(0,t.jsx)(n.p,{children:"Terdapat pelbagai teknik yang boleh kita laksanakan untuk mitigasi ralat. Kita akan membincangkan tiga, dalam susunan ketahanan ralat yang meningkat, tetapi juga, akibatnya, dalam susunan kos pengkomputeran yang meningkat. Namun, perlu diketahui bahawa ini adalah kawasan penyelidikan yang aktif \u2014 jadi kita mungkin akan terus mencipta yang baharu dan menambah baik yang lama."}),"\n",(0,t.jsx)(n.p,{children:"Pada tahap ketahanan 0, Transpiler tidak melakukan apa-apa pada litar anda."}),"\n",(0,t.jsx)(n.p,{children:"Pada tahap 1, ia memperkenalkan kaedah yang dipanggil Twirled Readout Error eXtinction (T-REX). T-REX menggunakan pilinan Pauli, seperti yang dibincangkan dalam bahagian penindasan ralat. Seperti yang disebutkan, memasukkan get rawak ke dalam litar boleh menjadikan walaupun hingar yang sangat rumit dan sukar dimodelkan kelihatan stokastik, dan jauh lebih mudah untuk diambil kira atau ditolak dalam pasca-pemprosesan."}),"\n",(0,t.jsx)(n.p,{children:"Pada tahap ketahanan 2, Zero Noise Extrapolation (ZNE) ditambah. Ini adalah teknik popular yang kita telah mempunyai banyak kejayaan terkini. Idea di sebalik ZNE mungkin agak mengejutkan \u2014 kita sebenarnya menambah hingar di atas apa yang sudah ada! Tetapi ini membolehkan kita mengekstrapolasikan dalam arah sebaliknya, untuk meramalkan apa yang hasilnya akan kelihatan jika ada semakin sedikit hingar."}),"\n",(0,t.jsx)(n.p,{children:"Menambah hingar boleh dicapai dalam beberapa cara yang berbeza. Sebagai contoh, kita boleh memanjangkan get untuk menjadikannya lebih lama dan dengan demikian lebih terdedah kepada ralat, atau menjalankan lebih banyak get yang akhirnya menghasilkan operasi identiti, supaya litar tidak berubah dari segi fungsional tetapi kita secara sengaja mengambil sampel lebih banyak hingar. Anda memang perlu melakukan ini untuk setiap litar dan setiap nilai jangkaan yang ingin anda jejaki, bagaimanapun \u2014 jadi anda boleh melihat bagaimana ia boleh akhirnya menjadi mahal dari segi pengkomputeran."}),"\n",(0,t.jsx)(n.p,{children:"Satu jenis ZNE khusus dipanggil Probabilistic Error Amplification (PEA). Setelah kita mempelajari model hingar untuk get, PEA berfungsi dengan mengambil sampel ralat dari model hingar itu dan sengaja menyuntiknya ke dalam litar. Ini belum tersedia dalam Qiskit lagi, tetapi akan ada kemudian tahun ini."}),"\n",(0,t.jsx)(n.p,{children:"Bentuk terakhir mitigasi ralat yang akan kita bincangkan adalah Probabilistic Error Cancellation (PEC). Daripada berada pada tahap ketahanan ke-3, PEC adalah keupayaan khas yang mesti anda hidupkan secara manual dalam Qiskit, kerana sumber pengkomputeran yang diperlukan tidak berskala dengan baik berbanding teknik mitigasi ralat yang lain. Anda mulakan dengan mempelajari tentang hingar yang mempengaruhi litar anda \u2014 jalankan litar pembelajaran-hingar atau pencirian-hingar untuk setiap lapisan unik get dua-qubit dalam litar anda. Keputusan ini membolehkan anda menggambarkan hingar dalam terma operator Pauli. Setelah anda mengetahui terma hingar ini, anda boleh mengubah litar anda supaya mereka secara berkesan mempunyai get Pauli bertentangan yang dibina masuk untuk membatalkan saluran hingar ini. Dalam beberapa cara, prosesnya serupa dengan cara fon kepala pembatal hingar berfungsi. Walau bagaimanapun, cara membatalkan hingar ini sangat mahal, dengan masa untuk berjalan yang berkembang dengan cepat dan secara eksponen dalam bilangan get, jadi ia mungkin bukan pilihan terbaik untuk litar yang sangat besar."}),"\n",(0,t.jsx)(n.h3,{id:"pasca-proses",children:"Pasca-proses"}),"\n",(0,t.jsx)(n.p,{children:"Peringkat pasca-proses adalah di mana kita memvisualisasikan dan menganalisis output litar kuantum kita. Terdapat beberapa alat Qiskit yang tersedia untuk anda melakukan ini, seperti modul visualisasi dan info-kuantum. Kita tidak akan merangkumi ini di sini, tetapi kita akan melihat modul-modul ini dalam tindakan apabila kita menyelami beberapa contoh aplikasi dalam pelajaran akan datang."}),"\n",(0,t.jsx)(n.h2,{id:"kesimpulan",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Semoga pelajaran ini memberi anda lawatan pantas tentang pertimbangan utama dan aliran kerja yang kita gunakan apabila kita ingin menjalankan pengkomputeran kuantum berskala utiliti. Ia padat dengan maklumat, dan banyaknya tidak akan meresap masuk sehingga kita melihat beberapa contoh sebenar di mana konsep teori ini dipraktikkan. Jadi, itulah yang akan menjadi sisa kursus ini. Lagipun, kursus ini bukan dipanggil Pengkomputeran Kuantum dalam Praktik tanpa sebab!"}),"\n",(0,t.jsx)(n.p,{children:"Kali berikutnya, kita akan melihat contoh tertentu tentang cara menggunakan aliran kerja corak Qiskit untuk mereka bentuk dan menjalankan litar kuantum yang menyelesaikan masalah klasik dari teori graf yang dipanggil MaxCut."})]})}function d(a={}){const{wrapper:n}={...(0,k.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},77815(a,n,e){e.d(n,{A:()=>i});const i=e.p+"assets/images/circuitdepth-e2f15da4f6d03fbe250110f56450f666.avif"},54776(a,n,e){e.d(n,{A:()=>i});const i="data:image/avif;base64,"},28453(a,n,e){e.d(n,{R:()=>u,x:()=>r});var i=e(96540);const t={},k=i.createContext(t);function u(a){const n=i.useContext(k);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:u(a.components),i.createElement(k.Provider,{value:n},a.children)}}}]);